import sys, os, re, time, json, yaml; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from kl import *
tee('k35')
cn, _ = up('main')
NS = ns('k35')
def pod(name, res='', ns_=NS, extra=''):
    return f'apiVersion: v1\nkind: Pod\nmetadata: {{name: {name}, namespace: {ns_}}}\nspec:\n  terminationGracePeriodSeconds: 0\n{extra}  containers:\n  - name: c\n    image: busybox:1.36\n    command: [sleep, "3600"]\n{res}'
def quota(ns_=NS):
    j = kj('get', 'resourcequota', 'q', '-n', ns_); return {k_: (j['status'].get('used', {}).get(k_), v) for k_, v in j['status'].get('hard', {}).items()}
def show_q(): return ', '.join(f'{k_}={u}/{h}' for k_, (u, h) in quota().items())
R = '    resources: {requests: {cpu: 400m, memory: 200Mi}, limits: {cpu: 500m, memory: 300Mi}}\n'
print(f'集群 {cn}')
k('apply', '-f', '-', input=f'apiVersion: v1\nkind: ResourceQuota\nmetadata: {{name: q, namespace: {NS}}}\nspec:\n  hard: {{pods: "3", requests.cpu: "1", limits.cpu: "2", requests.memory: 1Gi, limits.memory: 1Gi, count/configmaps: "4"}}\n')
time.sleep(2)
print('== 一:配额怎么记账——创建 Pod 之后 status.used 随之变化')
print(f'  ResourceQuota q(pods 3、requests.cpu 1、limits.cpu 2、requests.memory 1Gi、limits.memory 1Gi、count/configmaps 4)刚创建:{show_q()}')
for i in (1, 2):
    k('apply', '-f', '-', input=pod(f'p{i}', R)); time.sleep(1.5)
    print(f'  创建 p{i}(requests cpu 400m / memory 200Mi,limits cpu 500m / memory 300Mi)之后:{show_q()}')
print('== 二:超额——在创建 Pod 的那一刻被拒绝')
rc, o = k('apply', '-f', '-', input=pod('p3', R)); print(f'  第 3 个同样的 Pod(requests.cpu 会变成 1200m,超过 1):退出码 {rc};{re.sub(r"^.*Forbidden: ", "", o.strip())[:260]}')
rc, o = k('apply', '-f', '-', input=pod('s1', '    resources: {requests: {cpu: 100m, memory: 50Mi}, limits: {cpu: 100m, memory: 50Mi}}\n')); print(f'  换一个小的(100m / 50Mi,第 3 个 Pod):退出码 {rc};{o.strip()};{show_q()}')
rc, o = k('apply', '-f', '-', input=pod('s2', '    resources: {requests: {cpu: 100m, memory: 50Mi}, limits: {cpu: 100m, memory: 50Mi}}\n')); print(f'  再来一个小的(第 4 个 Pod,pods 已经 3/3):退出码 {rc};{re.sub(r"^.*Forbidden: ", "", o.strip())[:200]}')
print('  用 Deployment 创建时,Deployment 本身是创建成功的,被拒绝的是它的 ReplicaSet 去创建 Pod 的那一步:')
k('delete', 'pod', 'p1', 'p2', '-n', NS, '--wait=true', timeout=60)
k('apply', '-f', '-', input=f'apiVersion: apps/v1\nkind: Deployment\nmetadata: {{name: web, namespace: {NS}}}\nspec:\n  replicas: 5\n  selector: {{matchLabels: {{app: web}}}}\n  template:\n    metadata: {{labels: {{app: web}}}}\n    spec:\n      terminationGracePeriodSeconds: 0\n      containers: [{{name: c, image: busybox:1.36, command: [sleep, "3600"], resources: {{requests: {{cpu: 100m, memory: 50Mi}}, limits: {{cpu: 100m, memory: 50Mi}}}}}}]\n')
time.sleep(8)
rc, o = k('get', 'deploy', 'web', '-n', NS); print('    kubectl get deploy web:' + o.strip().splitlines()[-1])
ev = (kj('get', 'events', '-n', NS, '--field-selector', 'reason=FailedCreate') or {}).get('items', [])
print(f'    ReplicaSet 的 FailedCreate 事件:{ev[0]["message"][:230] if ev else "(没有)"}')
print(f'    配额:{show_q()}')
k('delete', 'deploy', 'web', '-n', NS, '--wait=true', timeout=60)
print('== 三:配额里有 requests / limits 时,Pod 必须写明——除非有 LimitRange 补默认值')
rc, o = k('apply', '-f', '-', input=pod('naked')); print(f'  什么都没写的 Pod:退出码 {rc};{re.sub(r"^.*Forbidden: ", "", o.strip())[:210]}')
k('apply', '-f', '-', input=f'apiVersion: v1\nkind: LimitRange\nmetadata: {{name: lr, namespace: {NS}}}\nspec:\n  limits: [{{type: Container, default: {{cpu: 200m, memory: 100Mi}}, defaultRequest: {{cpu: 100m, memory: 50Mi}}}}]\n')
rc, o = k('apply', '-f', '-', input=pod('naked')); print(f'  同命名空间加了一个 LimitRange(补默认值)之后同一个 Pod:退出码 {rc};{o.strip()};{show_q()}')
k('delete', 'pod', 'naked', '-n', NS, '--wait=true', timeout=60); k('delete', 'limitrange', 'lr', '-n', NS)
print('== 四:对象数量配额,和只数 BestEffort Pod 的范围(scope)')
for i in range(5): k('create', 'cm', f'c{i}', '-n', NS, '--from-literal=a=1')
rc, o = k('get', 'cm', '-n', NS, '-o', 'name'); print(f'  count/configmaps 上限 4:命名空间里原有 kube-root-ca.crt,c0~c4 里成功创建了 {len(o.strip().splitlines()) - 1} 个;{show_q()}')
rc, o = k('create', 'cm', 'one-more', '-n', NS, '--from-literal=a=1'); print(f'    再建一个:{re.sub(r"^.*Forbidden: ", "", o.strip())[:200]}')
NS2 = ns('k35b')
k('apply', '-f', '-', input=f'apiVersion: v1\nkind: ResourceQuota\nmetadata: {{name: be, namespace: {NS2}}}\nspec:\n  hard: {{pods: "1"}}\n  scopes: [BestEffort]\n')
time.sleep(1.5)
k('apply', '-f', '-', input=pod('be1', ns_=NS2)); rc, o = k('apply', '-f', '-', input=pod('be2', ns_=NS2)); print(f'  另一个命名空间里 scopes: [BestEffort]、pods: 1 的配额:第 1 个 BestEffort Pod 成功;第 2 个:退出码 {rc};{re.sub(r"^.*Forbidden: ", "", o.strip())[:200]}')
rc, o = k('apply', '-f', '-', input=pod('bu1', '    resources: {requests: {cpu: 10m}, limits: {cpu: 100m, memory: 50Mi}}\n', ns_=NS2)); print(f'    Burstable 的 Pod 不受这个配额管:退出码 {rc};{o.strip()}')
print(f'    配额 be 的用量:{ko("get", "resourcequota", "be", "-n", NS2, "-o", "jsonpath={.status.used}")}(只数了 BestEffort 的那一个)')
k('delete', 'pod', 'be1', '-n', NS2, '--wait=true', timeout=60); time.sleep(2)
print(f'  删除 be1 之后 be 的用量:{ko("get", "resourcequota", "be", "-n", NS2, "-o", "jsonpath={.status.used}")}')
rmns(NS); rmns(NS2)
